// ============================================================
// socket_helpers.c - Low-level socket helpers for FreeLang HTTP server
// FreeLang에서 extern fn으로 호출하는 C 헬퍼 함수들
// ============================================================

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// TCP 서버 소켓 생성 + bind + listen
long server_create(long port) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("[ERROR] socket");
        return -1;
    }

    int opt = 1;
    setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family      = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port        = htons((uint16_t)port);

    if (bind(sockfd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("[ERROR] bind");
        close(sockfd);
        return -1;
    }

    if (listen(sockfd, 10) < 0) {
        perror("[ERROR] listen");
        close(sockfd);
        return -1;
    }

    return (long)sockfd;
}

// 클라이언트 연결 수락
long server_accept(long sockfd) {
    struct sockaddr_in client;
    socklen_t len = sizeof(client);
    int fd = accept((int)sockfd, (struct sockaddr *)&client, &len);
    if (fd < 0) {
        perror("[ERROR] accept");
        return -1;
    }
    printf("[INFO] Client connected: %s\n", inet_ntoa(client.sin_addr));
    return (long)fd;
}

// 연결 닫기
long conn_close(long fd) {
    return (long)close((int)fd);
}

// 문자열 전송
long send_str(long fd, const char *str) {
    long len = (long)strlen(str);
    long sent = (long)write((int)fd, str, (size_t)len);
    return sent;
}

// 로그 출력 (printf wrapper)
long log_info(const char *msg) {
    return (long)printf("[SERVER] %s\n", msg);
}

long log_num(const char *label, long val) {
    return (long)printf("[SERVER] %s: %ld\n", label, val);
}

