// ============================================================
// http_server_real.fl - 정식 HTTP 서버 구현 (FreeLang)
// socket_helpers.c 와 연동하여 실제 TCP 소켓으로 동작
// ============================================================

// socket_helpers.c 에서 제공하는 외부 함수 선언
extern fn server_create(port: i64) -> i64;
extern fn server_accept(sockfd: i64) -> i64;
extern fn conn_close(fd: i64) -> i64;
extern fn send_str(fd: i64, str: string) -> i64;
extern fn log_info(msg: string) -> i64;
extern fn log_num(label: string, val: i64) -> i64;

// ============================================================
// 응답 생성 함수들
// ============================================================

fn send_response_200(fd: i64) -> i64 {
    send_str(fd, "HTTP/1.1 200 OK\r\n");
    send_str(fd, "Content-Type: text/html; charset=UTF-8\r\n");
    send_str(fd, "Content-Length: 120\r\n");
    send_str(fd, "Connection: close\r\n");
    send_str(fd, "Server: FreeLang/1.0\r\n");
    send_str(fd, "\r\n");
    send_str(fd, "<html><head><title>FreeLang HTTP</title></head>");
    send_str(fd, "<body><h1>Hello from FreeLang!</h1>");
    send_str(fd, "<p>Compiled: FreeLang -&gt; C -&gt; Binary</p></body></html>");
    return 200;
}

fn send_response_404(fd: i64) -> i64 {
    send_str(fd, "HTTP/1.1 404 Not Found\r\n");
    send_str(fd, "Content-Type: text/plain\r\n");
    send_str(fd, "Content-Length: 9\r\n");
    send_str(fd, "Connection: close\r\n");
    send_str(fd, "\r\n");
    send_str(fd, "Not Found");
    return 404;
}

fn send_response_health(fd: i64) -> i64 {
    send_str(fd, "HTTP/1.1 200 OK\r\n");
    send_str(fd, "Content-Type: application/json\r\n");
    send_str(fd, "Content-Length: 27\r\n");
    send_str(fd, "Connection: close\r\n");
    send_str(fd, "\r\n");
    send_str(fd, "{\"status\":\"ok\",\"lang\":\"fl\"}");
    return 200;
}

// ============================================================
// 클라이언트 처리
// ============================================================

fn handle_client(fd: i64, req_num: i64) -> i64 {
    var status: i64 = 0;

    // req_num 기반으로 라우팅 시뮬레이션
    // (실제 파싱은 C 레이어에서 처리)
    if (req_num == 2) {
        status = send_response_health(fd);
        log_info("Route: /health -> 200");
    }

    if (req_num != 2) {
        status = send_response_200(fd);
        log_info("Route: / -> 200");
    }

    conn_close(fd);
    log_num("Request handled, status", status);
    return status;
}

// ============================================================
// 메인 서버 루프
// ============================================================

fn main() -> i64 {
    var port: i64 = 8080;
    var max_req: i64 = 5;

    log_info("FreeLang HTTP Server starting...");
    log_num("Port", port);

    var sockfd: i64 = server_create(port);

    if (sockfd < 0) {
        log_info("FATAL: Failed to create server socket");
        return 1;
    }

    log_info("Server ready. Waiting for connections...");
    log_info("Try: curl http://localhost:8080/");

    var count: i64 = 0;
    while (count < max_req) {
        var client_fd: i64 = server_accept(sockfd);

        if (client_fd >= 0) {
            log_num("Connection", count + 1);
            handle_client(client_fd, count);
            count = count + 1;
        }
    }

    log_num("Total requests handled", count);
    log_info("Server shutting down.");
    conn_close(sockfd);

    return 0;
}

